fn sqlite_snapshot_wfc2d_retains_native_literal_identity_states(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();
 for case in corpus["literalIdentityStates"].as_array().unwrap(){
  let mut source=fixture();for tile in &mut source.tiles{tile.id=case["tileId"].as_str().unwrap().into();}for slot in &mut source.slots{slot.id=case["slotId"].as_str().unwrap().into();slot.pinned_tile_id=Some(case["pinTileId"].as_str().unwrap().into());}for rule in &mut source.rules{rule.id=case["ruleId"].as_str().unwrap().into();rule.tile_a_id=case["tileAId"].as_str().unwrap().into();rule.tile_b_id=case["tileBId"].as_str().unwrap().into();}for edge in &mut source.edges{edge.id=case["edgeId"].as_str().unwrap().into();edge.from_slot_id=case["fromSlotId"].as_str().unwrap().into();edge.to_slot_id=case["toSlotId"].as_str().unwrap().into();}
  let native:[Wfc2dSnapshot;2]=[store::ArtifactPack::decode_pack(&store::ArtifactPack::encode_pack(&source)).unwrap(),store::ArtifactDsl::parse_dsl(&store::ArtifactDsl::print_dsl(&source)).unwrap()];
  for actual in native{assert!(actual.tiles.iter().all(|t|t.id==case["tileId"].as_str().unwrap()));assert!(actual.slots.iter().all(|s|s.id==case["slotId"].as_str().unwrap()&&s.pinned_tile_id.as_deref()==case["pinTileId"].as_str()));assert_eq!(actual.rules[0].tile_a_id,source.rules[0].tile_a_id);assert_eq!(actual.edges[0].from_slot_id,source.edges[0].from_slot_id);}
  let actual=restore(&project(&source)).unwrap();assert_eq!(store::ArtifactPack::encode_pack(&actual),store::ArtifactPack::encode_pack(&source));
 }
}
#[test]

fn sqlite_snapshot_wfc2d_native_real_collection_and_utf_frontiers(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let n=corpus["controlledAdmission"]["items"].as_u64().unwrap()as usize;let cancel=corpus["controlledAdmission"]["cancelAfter"].as_u64().unwrap()as usize;
 let mut source=fixture();let first=source.slots[0].clone();source.slots=(0..n).map(|i|{let mut slot=first.clone();slot.id=i.to_string();slot}).collect();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(&source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(&source))};
  let mut hit=false;let result=Wfc2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==n&&p.completed==cancel{hit=true;false}else{true}},SqliteDatabaseLimits::default()));assert!(result.is_err());assert!(hit);
  let mut hit=false;let result=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::EncodeNative&&p.total==n&&p.completed==cancel{hit=true;false}else{true}},SqliteDatabaseLimits::default()));assert!(result.is_err());assert!(hit);
  assert!(Wfc2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()})).is_err());assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2,..SqliteDatabaseLimits::default()})).is_err());
 }
 source.schema="🧬".repeat(corpus["controlledAdmission"]["textBytes"].as_u64().unwrap()as usize/4);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(&source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(&source))};
  for phase in[SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::EncodeNative]{let mut hit=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==phase&&p.total>=65536&&p.completed>=65536&&p.completed<p.total{hit=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());let result=if phase==SqliteSnapshotPhase::DecodeNative{Wfc2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut control).map(|_|())}else{source.encode_sqlite_snapshot_native(encoding,&mut control).map(|_|())};assert!(result.is_err());assert!(hit);}
  let limits=SqliteDatabaseLimits{max_value_bytes:corpus["controlledAdmission"]["smallValueBudget"].as_u64().unwrap()as usize,..SqliteDatabaseLimits::default()};assert!(Wfc2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());
 }
}

