 let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();
 for state in f["literalIdentityStates"].as_array().unwrap(){
  let mut source=fixture();for(tile,id)in source.tiles.iter_mut().zip(state["tileIds"].as_array().unwrap()){tile.id=id.as_str().unwrap().into();}
  source.rules[0].id=state["ruleId"].as_str().unwrap().into();source.rules[0].tile_a_id=state["tileAId"].as_str().unwrap().into();source.rules[0].tile_b_id=state["tileBId"].as_str().unwrap().into();source.rules.push(source.rules[0].clone());source.pinned[0].tile_id=state["pinnedTileId"].as_str().unwrap().into();
  for actual in[<Grid2dSnapshot as store::ArtifactPack>::decode_pack(&store::ArtifactPack::encode_pack(&source)).unwrap(),<Grid2dSnapshot as store::ArtifactDsl>::parse_dsl(&store::ArtifactDsl::print_dsl(&source)).unwrap()]{
   assert_eq!(serde_json::to_value(actual.tiles.iter().map(|tile|&tile.id).collect::<Vec<_>>()).unwrap(),state["tileIds"]);
   assert_eq!(actual.rules.len(),2);assert_eq!(actual.rules[0].id,actual.rules[1].id);assert_eq!(actual.rules[0].tile_a_id,state["tileAId"].as_str().unwrap());assert_eq!(actual.rules[0].tile_b_id,state["tileBId"].as_str().unwrap());assert_eq!(actual.pinned[0].tile_id,state["pinnedTileId"].as_str().unwrap());
   let database=actual.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
   let restored=restore(&database).unwrap();assert_eq!(store::ArtifactPack::encode_pack(&restored),store::ArtifactPack::encode_pack(&actual));
  }
 }
}
