 let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let admission=&f["controlledAdmission"];
 let n=admission["collectionItems"].as_u64().unwrap() as usize;let cancel=admission["cancelAfter"].as_u64().unwrap() as usize;
