 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(&source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(&source))};
  for phase in[SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::EncodeNative]{
   let mut interior=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==phase&&p.total>=65536&&p.completed>=65536&&p.completed<p.total{interior=true;false}else{true}};
   let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());
   let error=if phase==SqliteSnapshotPhase::DecodeNative{Grid2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut control).unwrap_err()}else{source.encode_sqlite_snapshot_native(encoding,&mut control).unwrap_err()};
   assert!(interior);assert!(error.kind == semio_framework_value::ValueRefusalKind::Canceled);
  }
  assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:admission["smallOwnedBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()})).is_err());
