fn sqlite_snapshot_generation_intrinsic_text_preserves_numeric_variants(){
 use semio_framework_artifact_playbook_playbook::{GenerationPlayState,FormGeneration};
 use semio_framework_value::Number;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../🫀️core/🧬️generation/🪶️sqlite/🧫️fixtures/🚦️native-controls.json")).unwrap();
 let cases=fixture["intrinsicNumbers"].as_array().unwrap();
 for case in cases{let value=case["value"].as_str().unwrap();let oracle:serde_json::Value=serde_json::from_str(value).unwrap();match case["variant"].as_str().unwrap(){"int"=>assert_eq!(oracle.as_i64().unwrap(),value.parse::<i64>().unwrap()),"uint"=>assert_eq!(oracle.as_u64().unwrap(),value.parse::<u64>().unwrap()),_=>assert_eq!(oracle.as_f64().unwrap().to_bits(),value.parse::<f64>().unwrap().to_bits())}}
 for case in cases{
  let value=case["value"].as_str().unwrap();let number=match case["variant"].as_str().unwrap(){"int"=>Number::Int(value.parse().unwrap()),"uint"=>Number::UInt(value.parse().unwrap()),_=>Number::Float(value.parse().unwrap())};
  let source=Generation2dSnapshotRead::new(Generation2dSnapshot{host_snapshot:Default::default(),generation:GenerationPlayState{selected_generation_id:None,preview_text:None,generations:vec![FormGeneration{id:"numeric".into(),name:"numeric".into(),values:semio_framework_artifact_playbook_playbook::PlaybookValues::from([("sample".into(),semio_framework_value::DslValue::Number(number))])}]}.into()});
  let text=<Generation2dSnapshot as store::ArtifactDsl>::print_dsl(&source);assert!(text.contains(&format!("sample={}",case["literal"].as_str().unwrap())),"{} {value}: {text}",case["variant"]);
  let ordinary=Generation2dSnapshotRead::new(<Generation2dSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap());
  let controlled=Generation2dSnapshotRead::new(Generation2dSnapshot::decode_sqlite_snapshot_native(&store::os_io::IoPayload::Text(text),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap());
  for decoded in [&ordinary,&controlled]{let semio_framework_value::DslValue::Number(actual)=decoded.generation.generations[0].values.get("sample").unwrap()else{panic!("numeric value changed")};match(number,*actual){(Number::Int(expected),Number::Int(actual))=>assert_eq!(actual,expected),(Number::UInt(expected),Number::UInt(actual))=>assert_eq!(actual,expected),(Number::Float(expected),Number::Float(actual))=>assert_eq!(actual.to_bits(),expected.to_bits()),_=>panic!("numeric variant changed: {number:?} -> {actual:?}")}}
 }
 eprintln!("[DEBUG] Generation intrinsic numeric Text cases={} independentSerde=true ordinaryAndControlled=true",cases.len());
}
