fn sqlite_snapshot_generation2d_wide_owned_answer_row_frontier_and_interior_cancel(){
 use semio_framework_artifact_playbook_playbook::{GenerationPlayState,FormGeneration};
 let f:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../🫀️core/🧬️generation/🪶️sqlite/🧫️fixtures/🚦️native-controls.json")).unwrap();let width=f["rowFrontier"]["width"].as_u64().unwrap()as usize;let cancel=f["rowFrontier"]["cancelAt"].as_u64().unwrap()as usize;
 let values=(0..width).map(|index|semio_framework_value::DslValue::Number(semio_framework_value::Number::UInt(index as u64))).collect();let generation=GenerationPlayState{selected_generation_id:None,preview_text:None,generations:vec![FormGeneration{id:"wide borrowed census".into(),name:"".into(),values:semio_framework_artifact_playbook_playbook::PlaybookValues::from([("wide".into(),semio_framework_value::DslValue::Array(values))])}]}.into();let host_snapshot=semio_framework_artifact_flow_flow::FlowHostSnapshot{schema:"flow.host_snapshot".into(),camera:semio_framework_artifact_flow_flow::CameraJson{x:0.0,y:0.0,zoom:1.0},widgets:Vec::new(),synapses:Vec::new(),layout:semio_framework_artifact_flow_flow::OrderedMap::new()};let source=Generation2dSnapshotRead::new(Generation2dSnapshot{host_snapshot,generation});let database=project(&source);let rows=sqlite_rows(&database);assert_eq!(rows,database.tables.iter().map(|table|table.rows.len()).sum::<usize>());assert_eq!(rows,5+2*width);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<Generation2dSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<Generation2dSnapshot as store::ArtifactDsl>::print_dsl(&source))};for offset in f["rowFrontier"]["limitOffsets"].as_array().unwrap(){let maximum=(rows as i64+offset.as_i64().unwrap())as usize;let limits=SqliteDatabaseLimits{max_rows:maximum,..SqliteDatabaseLimits::default()};let output=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits));let input=Generation2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits));if maximum==rows{assert_eq!(output.unwrap(),payload);let restored=Generation2dSnapshotRead::new(input.unwrap());assert_eq!(project(&restored),database);}else{assert!(output.as_ref().is_err_and(|error|error.message.contains("row")),"output {output:?}");match input{Ok(value)=>{value.retire_sqlite_snapshot();panic!("wide complete input admitted excessive semantic rows")},Err(error)=>assert!(error.message.contains("row"),"{error}")}}}
  for phase in[SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::EncodeNative]{let mut interior=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==phase&&p.completed>=cancel&&(p.total==0||p.completed<p.total){interior=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());let rejected=if phase==SqliteSnapshotPhase::DecodeNative{match Generation2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut control){Ok(value)=>{value.retire_sqlite_snapshot();false},Err(_)=>true}}else{source.encode_sqlite_snapshot_native(encoding,&mut control).is_err()};assert!(rejected&&interior,"{phase:?}");}
 }
}
