fn sqlite_snapshot_generation_native_row_frontier_matches_complete_relational_entities(){
 let source=fixture();let database=project(&source);let rows=database.tables.iter().map(|table|table.rows.len()).sum::<usize>();assert!(rows>20);assert_eq!(sqlite_rows(&database),rows);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<Generation2dSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<Generation2dSnapshot as store::ArtifactDsl>::print_dsl(&source))};for maximum in[rows-1,rows]{let limits=SqliteDatabaseLimits{max_rows:maximum,..SqliteDatabaseLimits::default()};let output=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits));let input=Generation2dSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits));if maximum==rows{assert_eq!(output.unwrap(),payload);let decoded=Generation2dSnapshotRead::new(input.unwrap());assert_eq!(project(&decoded),project(&source));}else{assert!(output.as_ref().is_err_and(|e|e.message.contains("row")),"output {output:?}");match input{Ok(value)=>{value.retire_sqlite_snapshot();panic!("complete native input admitted excessive semantic rows")},Err(error)=>assert!(error.message.contains("row"),"{error}")}}}}
}
#[test]

fn sqlite_snapshot_procedural_generation2d_independent_entity_renumbering_preserves_owned_state(){
 use std::io::Write;use std::process::{Command,Stdio};
 let source=fixture();let expected=project(&source);let bytes=export_sqlite_database(&expected,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let f:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../🫀️core/🧬️generation/🪶️sqlite/🧫️fixtures/🚦️native-controls.json")).unwrap();let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));const offset=Number(process.env.SEMIO_GENERATION_TEST_ID_OFFSET);if(!Number.isSafeInteger(offset)||offset<=0)throw Error('identity offset');const q=s=>'"'+s.replaceAll('"','""')+'"';d.exec('PRAGMA foreign_keys=OFF');for(const{name}of d.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all()){const columns=new Set(d.query('PRAGMA foreign_key_list('+q(name)+')').all().map(row=>row.from).filter(name=>name!=='id'));const assignments=['id=id+'+offset,...[...columns].map(name=>q(name)+'='+q(name)+'+'+offset)];d.exec('UPDATE '+q(name)+' SET '+assignments.join(','));}if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('renumbered integrity');await Bun.write(Bun.stdout,d.serialize());"#;
