fn sqlite_snapshot_procedural_generation3d_wire_primitive_controlled_binding_preserves_literal_ownership(){
 use semio_framework_dsl_record::DslField;
use semio_framework_value::DslValue;
use semio_framework_dsl_record::FieldValue;
use semio_framework_dsl_record::Wire;
use semio_framework_dsl_record::WireNode;
use semio_framework_dsl_record::WireEdgeLabel;
use semio_framework_dsl_record::WireValue;use std::io::Write;use std::process::{Command,Stdio};
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../🫀️core/🧬️generation/🪶️sqlite/🧫️fixtures/🚦️native-controls.json")).unwrap();let f=&corpus["wireBinding"];
 let node=|value:&serde_json::Value|WireNode{id:value["id"].as_str().unwrap().into(),kind:value["kind"].as_str().map(str::to_owned),port:value["port"].as_str().map(str::to_owned)};
 let word=u64::from_str_radix(f["floatBits"].as_str().unwrap(),16).unwrap();let bytes=f["bytes"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap() as u8).collect::<Vec<_>>();let key=f["duplicateKey"].as_str().unwrap();let unsigned=f["unsigned"].as_str().unwrap().parse::<u64>().unwrap();let depth=f["depth"].as_u64().unwrap() as usize;
 let mut properties=semio_framework_value::DslValue::Object(vec![(key.into(),semio_framework_value::DslValue::uint(unsigned)),(key.into(),semio_framework_value::DslValue::float(f64::from_bits(word))),("octets".into(),semio_framework_value::DslValue::Bytes(bytes.clone()))]);for _ in 0..depth{properties=semio_framework_value::DslValue::Array(vec![properties]);}
 let source=Wire(WireValue{from:node(&f["from"]),edge:Some((f["directed"].as_bool().unwrap(),node(&f["to"]))),edge_label:WireEdgeLabel{id:f["edgeLabel"]["id"].as_str().map(str::to_owned),kind:f["edgeLabel"]["kind"].as_str().map(str::to_owned)},properties});
 let maximum=f["maximumOwnedBytes"].as_u64().unwrap() as usize;let mut accepted=|_|true;let mut output=semio_framework_value::NativeEncodeControl::new(maximum,&mut accepted);let field=source.to_value_controlled(&mut output).expect("Wire must project its literal fields with cumulative control");assert!(output.owned_bytes()>0);
 let mut accepted=|_|true;let mut input=semio_framework_value::NativeDecodeControl::new(maximum,&mut accepted);let actual=semio_framework_dsl_record::Wire::from_value_controlled(&field,&mut input).expect("Wire must construct its literal fields with cumulative control");assert!(input.owned_bytes()>0);assert_eq!(actual.0.from,source.0.from);assert_eq!(actual.0.edge,source.0.edge);assert_eq!(actual.0.edge_label,source.0.edge_label);
 let mut value=&actual.0.properties;for _ in 0..depth{if let semio_framework_value::DslValue::Array(items)=value{assert_eq!(items.len(),1);value=&items[0]}else{panic!("Wire nested intrinsic ownership differs")}}let members=value.as_object().unwrap();assert_eq!(members.len(),3);assert_eq!(members[0].0,key);assert_eq!(members[1].0,key);assert_eq!(members[0].1,semio_framework_value::DslValue::uint(unsigned));assert_eq!(members[1].1.as_f64().unwrap().to_bits(),word);assert_eq!(members[2].1,semio_framework_value::DslValue::Bytes(bytes.clone()));
 let wire=&actual.0;let (directed,to)=wire.edge.as_ref().unwrap();let oracle=serde_json::json!({"expected":f,"actual":{"from":{"id":wire.from.id,"kind":wire.from.kind,"port":wire.from.port},"to":{"id":to.id,"kind":to.kind,"port":to.port},"directed":directed,"edgeLabel":{"id":wire.edge_label.id,"kind":wire.edge_label.kind},"unsigned":members[0].1.as_u64().unwrap().to_string(),"floatBits":format!("{:016x}",members[1].1.as_f64().unwrap().to_bits()),"bytes":bytes,"duplicateKeys":[members[0].0,members[1].0]}});
