fn sqlite_snapshot_energy_independent_engine_edits_every_ieee_field_then_erased_roundtrips(){
 use std::io::Write;use std::process::{Command,Stdio};use store::sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SnapshotEncoding};let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let bytes=export_sqlite_database(&energy_project(&full_energy_fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let provider=store::ArtifactCodec::bare::<EnergyModelSnapshot,crate::EnergyModelMutation>(crate::ENERGY_MODEL_DOCUMENT_SCHEMA).snapshot_sqlite.unwrap();let dialect=store::io_schema::ArtifactDialect{artifact_kind:"s.energy.model".into(),standard:"1".into(),subset:"*".into()};
 let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true}),bits=BigInt('0x'+process.env.SEMIO_TEST_WORD),signed=BigInt.asIntN(64,bits),b=new ArrayBuffer(8),v=new DataView(b);v.setBigUint64(0,bits);const number=v.getFloat64(0),kind=Number.isNaN(number)?'nan':number===Infinity?'positiveInfinity':number===-Infinity?'negativeInfinity':'finite';let count=0;for(const table of d.query(\"SELECT name FROM sqlite_schema WHERE type='table'\").all()){for(const column of d.query('PRAGMA table_info('+table.name+')').all()){if(column.type!=='REAL')continue;const c=column.name,n=Number(d.query('SELECT COUNT(*) AS n FROM '+table.name+' WHERE '+c+'_ieee754_bits IS NOT NULL').get().n);count+=n;d.query('UPDATE '+table.name+' SET '+c+'=?,'+c+'_ieee754_bits=?,'+c+'_ieee754_class=? WHERE '+c+'_ieee754_bits IS NOT NULL').run(Number.isNaN(number)?null:number,signed,kind);for(const row of d.query('SELECT '+c+'_ieee754_bits AS bits FROM '+table.name+' WHERE '+c+'_ieee754_bits IS NOT NULL').all())if(row.bits!==signed)throw Error('exact IEEE companion');}}if(count!==173)throw Error('all173 Energy words count '+count);if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";
 for word in corpus["binary64Words"].as_array().unwrap(){let mut child=Command::new("bun").args(["-e",script]).env("SEMIO_TEST_WORD",word.as_str().unwrap()).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let db=import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let source=EnergyModelSnapshot::from_sqlite_database(&db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(energy_project(&source),db);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let exported=(provider.export)(crate::ENERGY_MODEL_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(exported,db);assert_eq!((provider.import)(crate::ENERGY_MODEL_DOCUMENT_SCHEMA,&dialect,exported,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value,payload);}}
}
